import java.util.Scanner;

public class SchoolAdmission {
    private String studName;
    private String stream;
    private double marksAvg;
    private double fee;

    public SchoolAdmission() {
        studName = "";
        stream = "";
        marksAvg = 0.0;
        fee = 0.0;
    }

    public void register() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Student Name: ");
        studName = in.nextLine();
        System.out.print("Enter Average Marks (%): ");
        marksAvg = in.nextDouble();
    }

    public void computeFee() {
        if (marksAvg >= 85.0) {
            stream = "SCIENCE";
            fee = 45000.0;
        } else if (marksAvg >= 70.0) {
            stream = "COMMERCE";
            fee = 38000.0;
        } else if (marksAvg >= 55.0) {
            stream = "HUMANITIES";
            fee = 30000.0;
        } else {
            stream = "NOT ADMITTED";
            fee = 0.0;
        }

        if (marksAvg >= 90.0 && fee > 0) {
            fee -= (0.20 * fee); // 20% scholarship waiver
        }
    }

    public void display() {
        System.out.println("\n============== ADMISSION ALLOCATION ==============");
        System.out.println("Student Name     : " + studName);
        System.out.println("Percentage Marks : " + marksAvg + "%");
        System.out.println("Allocated Stream : " + stream);
        System.out.println("Net Tuition Fee  : Rs. " + fee);
        System.out.println("==================================================");
    }

    public static void main(String[] args) {
        SchoolAdmission adm = new SchoolAdmission();
        adm.register();
        adm.computeFee();
        adm.display();
    }
}
```

