import java.util.Scanner;

public class TargetSumPairs {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 10;
        int[] arr = new int[N];

        System.out.println("Enter " + N + " distinct integers:");
        for (int i = 0; i < N; i++) arr[i] = sc.nextInt();

        System.out.print("Enter target sum K: ");
        int k = sc.nextInt();

        int pairCount = 0;
        System.out.println("\nPairs with sum = " + k + ":");

        for (int i = 0; i < N - 1; i++) {
            for (int j = i + 1; j < N; j++) {
                if (arr[i] + arr[j] == k) {
                    System.out.println("(" + arr[i] + ", " + arr[j] + ")");
                    pairCount++;
                }
            }
        }

        if (pairCount == 0) {
            System.out.println("No pairs found with sum " + k + ".");
        } else {
            System.out.println("Total pairs found = " + pairCount);
        }
    }
}
```

