import java.util.Scanner;

public class TribonacciCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter positive integer X: ");
        int x = sc.nextInt();

        if (x < 0) {
            System.out.println("Negative numbers are not in Tribonacci sequence.");
            return;
        }

        int t0 = 0, t1 = 1, t2 = 1;
        boolean isTribonacci = (x == 0 || x == 1);

        while (t2 < x) {
            int tNext = t0 + t1 + t2;
            if (tNext == x) {
                isTribonacci = true;
                break;
            }
            t0 = t1;
            t1 = t2;
            t2 = tNext;
        }

        System.out.println();
        if (isTribonacci) {
            System.out.println(x + " is a term in the TRIBONACCI SEQUENCE.");
        } else {
            System.out.println(x + " is NOT in the Tribonacci Sequence.");
        }
    }
}
```

