import java.util.Scanner;

public class MatrixRotate90Clockwise {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter square matrix dimension N: ");
        int n = in.nextInt();

        int[][] mat = new int[n][n];
        System.out.println("Enter " + (n * n) + " elements:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) mat[i][j] = in.nextInt();
        }

        System.out.println("\nOriginal Matrix:");
        printMatrix(mat);

        // Step 1: Transpose
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int temp = mat[i][j];
                mat[i][j] = mat[j][i];
                mat[j][i] = temp;
            }
        }

        // Step 2: Reverse each row
        for (int i = 0; i < n; i++) {
            int left = 0, right = n - 1;
            while (left < right) {
                int temp = mat[i][left];
                mat[i][left] = mat[i][right];
                mat[i][right] = temp;
                left++;
                right--;
            }
        }

        System.out.println("\nMatrix after 90 Degrees Clockwise Rotation:");
        printMatrix(mat);
    }

    private static void printMatrix(int[][] a) {
        for (int[] row : a) {
            for (int v : row) System.out.printf("%5d", v);
            System.out.println();
        }
    }
}
```

