public class OverloadInterest {
    public double calculate(double p, double r, double t) {
        return (p * r * t) / 100.0;
    }

    public double calculate(double p, double r, int n, double t) {
        double ratePerPeriod = r / (100.0 * n);
        double totalPeriods = n * t;
        return p * Math.pow(1.0 + ratePerPeriod, totalPeriods);
    }

    public static void main(String[] args) {
        OverloadInterest fin = new OverloadInterest();

        double si = fin.calculate(10000.0, 7.5, 3.0);
        System.out.printf("Simple Interest (P=10k, R=7.5%%, T=3 yrs) = Rs. %.2f\n", si);

        double ci = fin.calculate(10000.0, 7.5, 4, 3.0);
        System.out.printf("Compound Interest Amount (Quarterly)     = Rs. %.2f\n", ci);
    }
}
```

